def ends_doubled(values):
    """Double the first and last items."""
    def double(n):
        """Twice n."""
        return n * 2

    return (double(values[0]), double(values[-1]))


print(ends_doubled([1, 2, 7]))
# Hidden checks
assert _delta_output == '(2, 14)\n'

